import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, float, fract, sin, dot, add, mul, sub, smoothstep, length } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, Box3, Vector3 } = ctx.THREE;

  const root = new Group();
  root.name = 'kinetic-hero-headline';

  const colors = (config.intent && config.intent.visualSpec && config.intent.visualSpec.colors) || {};
  const cBg = colors.background || '#0b0b10';
  const cBg2 = (colors.gradientStops && colors.gradientStops[1] && colors.gradientStops[1].hex) || '#13131a';
  const cPaper = colors.paper || '#e8ecf2';
  const cAccent = colors.accent || '#ff2a38';

  const disposables = [];
  const timelines = [];
  const primHandles = [];

  // ---------------------------------------------------------------
  // BACKDROP: full-frame engineered vertical gradient + 1.5% grain
  // (dark-first: #0b0b10 bottom -> #13131a top, covers entire frame)
  // ---------------------------------------------------------------
  const bgGeo = new PlaneGeometry(9, 7);
  const bgMat = new MeshBasicNodeMaterial();
  {
    const col0 = new Color(cBg);
    const col1 = new Color(cBg2);
    const c0 = vec3(col0.r, col0.g, col0.b);
    const c1 = vec3(col1.r, col1.g, col1.b);
    const grad = mix(c0, c1, uv().y);
    const n = fract(mul(sin(dot(mul(uv(), float(487.0)), vec2(127.1, 311.7))), float(43758.5453)));
    const grain = mul(sub(n, float(0.5)), float(0.015));
    bgMat.colorNode = add(grad, grain);
  }
  const backdrop = new Mesh(bgGeo, bgMat);
  backdrop.position.set(0, 0, -2.2);
  root.add(backdrop);
  disposables.push(bgGeo, bgMat);

  // ---------------------------------------------------------------
  // MID-DEPTH ACCENT GLOW: faint machined red halo behind the hero
  // ---------------------------------------------------------------
  const glowGeo = new PlaneGeometry(4.2, 2.2);
  const glowMat = new MeshBasicNodeMaterial();
  {
    const ca = new Color(cAccent);
    const d = length(sub(uv(), vec2(0.5, 0.5)));
    glowMat.colorNode = vec3(ca.r, ca.g, ca.b);
    glowMat.opacityNode = mul(smoothstep(float(0.5), float(0.05), d), float(0.10));
    glowMat.transparent = true;
    glowMat.depthWrite = false;
  }
  const glow = new Mesh(glowGeo, glowMat);
  glow.position.set(0, 0.35, -1.6);
  root.add(glow);
  disposables.push(glowGeo, glowMat);

  // ---------------------------------------------------------------
  // TEXT CONTENT (verbatim from spec items)
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let captionStr = 'NOVA ATELIER / CALIBRE PROGRAM';
  let heroStr = 'TIME, MACHINED.';
  let subheadStr = 'Every calibre begins as a solid billet.';
  for (const item of items) {
    if (item.role === 'caption') captionStr = String(item.text);
    else if (item.role === 'hero') heroStr = String(item.text);
    else if (item.role === 'subhead') subheadStr = String(item.text);
  }

  // ---- measurement helpers: scale glyph planes to exact scene-unit
  // ---- em heights (previous build rendered text at raw pixel scale,
  // ---- blowing white glyph planes across the whole frame)
  const _box = new Box3();
  const _size = new Vector3();
  const measure = (obj) => {
    _box.setFromObject(obj);
    _box.getSize(_size);
    return { w: _size.x, h: _size.y, minX: _box.min.x, maxX: _box.max.x, minY: _box.min.y, maxY: _box.max.y };
  };
  const disposeObj = (obj) => {
    obj.traverse((c) => {
      if (c.geometry && c.geometry.dispose) c.geometry.dispose();
      if (c.material && c.material.dispose) c.material.dispose();
    });
  };
  // give every text object its own material instances so opacity
  // animation on one block never bleeds into another
  const decoupleMaterials = (obj) => {
    obj.traverse((c) => {
      if (c.material && c.material.clone) {
        c.material = c.material.clone();
        c.material.transparent = true;
      }
    });
  };
  const setOpacity = (obj, v) => {
    obj.traverse((c) => {
      if (c.material) {
        c.material.transparent = true;
        c.material.opacity = v;
      }
    });
  };
  // scale a text object so its measured height equals targetEm scene units
  const fitToEm = (obj, targetEm, fontSize) => {
    const m = measure(obj);
    const s = m.h > 1e-5 ? targetEm / m.h : targetEm / fontSize;
    obj.scale.setScalar(s);
    return s;
  };
  // recenter a (scaled) text object's bounding box onto its local origin
  const centerOnOrigin = (obj) => {
    const m = measure(obj);
    obj.position.x -= (m.minX + m.maxX) / 2;
    obj.position.y -= (m.minY + m.maxY) / 2;
  };

  // ---------------------------------------------------------------
  // CAPTION KICKER at y = 1.15 (accent, mono, tracked-out caps)
  // ---------------------------------------------------------------
  const captionWrap = new Group();
  const caption = ctx.fontAtlas.createText(captionStr, {
    fontSize: 18,
    color: cAccent,
    align: 'center',
    letterSpacingPx: 2.2,
  });
  decoupleMaterials(caption);
  fitToEm(caption, 0.09, 18);
  centerOnOrigin(caption);
  captionWrap.add(caption);
  captionWrap.position.set(0, 1.15, 0.05);
  root.add(captionWrap);

  // ---------------------------------------------------------------
  // HERO: per-word dimensional type at em 0.62, z parallax steps
  // ---------------------------------------------------------------
  const heroGroup = new Group();
  heroGroup.position.set(0, 0.4, 0);
  root.add(heroGroup);

  const words = heroStr.split(' ').filter((w) => w.length > 0);
  const HERO_EM = 0.62;
  const GAP = 0.25;

  // derive one uniform scale from the full line so per-word heights match
  const lineProbe = ctx.fontAtlas.createText(heroStr, {
    fontSize: 124,
    color: cPaper,
    align: 'center',
    letterSpacingPx: -1.2,
  });
  const probeM = measure(lineProbe);
  const heroScale = probeM.h > 1e-5 ? HERO_EM / probeM.h : HERO_EM / 124;
  disposeObj(lineProbe);

  const zSteps = words.length === 3 ? [0.12, 0.0, -0.12] : words.length === 2 ? [0.12, -0.12] : [0.0];

  const wordWraps = [];
  const wordMeta = [];
  let totalW = 0;
  words.forEach((word) => {
    const wObj = ctx.fontAtlas.createText(word, {
      fontSize: 124,
      color: cPaper,
      align: 'center',
      letterSpacingPx: -1.2,
    });
    decoupleMaterials(wObj);
    wObj.scale.setScalar(heroScale);
    centerOnOrigin(wObj);
    const m = measure(wObj);
    wordMeta.push({ obj: wObj, w: m.w });
    totalW += m.w;
  });
  totalW += GAP * (words.length - 1);

  let cursor = -totalW / 2;
  wordMeta.forEach((meta, i) => {
    const wrap = new Group();
    wrap.add(meta.obj);
    wrap.position.set(cursor + meta.w / 2, 0, zSteps[Math.min(i, zSteps.length - 1)] || 0);
    heroGroup.add(wrap);
    wordWraps.push(wrap);
    cursor += meta.w + GAP;
  });

  // ---------------------------------------------------------------
  // ACCENT UNDERLINE: 2.6 x 0.045, emissive 1.2, left-anchored reveal
  // ---------------------------------------------------------------
  const ruleGeo = new PlaneGeometry(2.6, 0.045);
  ruleGeo.translate(1.3, 0, 0); // anchor left edge at local origin
  const ruleMat = new MeshStandardNodeMaterial({
    color: new Color(cAccent),
    emissive: new Color(cAccent),
    emissiveIntensity: 1.2,
    roughness: 0.6,
    metalness: 0.1,
  });
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(-1.3, -0.05, 0.06);
  rule.scale.x = 0.0001;
  root.add(rule);
  disposables.push(ruleGeo, ruleMat);

  // ---------------------------------------------------------------
  // SUBHEAD at y = -0.65 (em 0.2, fades up from -0.85)
  // ---------------------------------------------------------------
  const subheadWrap = new Group();
  const subhead = ctx.fontAtlas.createText(subheadStr, {
    fontSize: 40,
    color: cPaper,
    align: 'center',
    letterSpacingPx: 0.8,
  });
  decoupleMaterials(subhead);
  fitToEm(subhead, 0.2, 40);
  centerOnOrigin(subhead);
  subheadWrap.add(subhead);
  subheadWrap.position.set(0, -0.85, 0.05);
  root.add(subheadWrap);

  // initial hidden states
  setOpacity(subhead, 0);
  setOpacity(caption, 0);
  wordMeta.forEach((m) => setOpacity(m.obj, 0));
  wordWraps.forEach((w) => { w.position.y += 0.35; });
  captionWrap.position.y += 0.2;

  // ---------------------------------------------------------------
  // CINEMATIC PRIMITIVES (from config, applied via ctx.primitives)
  // ---------------------------------------------------------------
  const prims = config.cinematicPrimitives ?? [];
  for (const primitive of prims) {
    const fn = ctx.primitives[primitive.name];
    if (fn) {
      const handle = fn(heroGroup, primitive.params || {});
      if (handle) primHandles.push(handle);
    }
  }

  // ---------------------------------------------------------------
  // MOTION: staggered kinetic rise, weighted settle, underline, subhead
  // ---------------------------------------------------------------
  const glyphCount = heroStr.replace(/\s/g, '').length;
  const lastGlyphLand = 0.1 + (glyphCount - 1) * 0.06 + 0.7;

  const tl = gsap.timeline();
  timelines.push(tl);

  // caption fade-up first
  const capState = { o: 0 };
  tl.to(captionWrap.position, { y: 1.15, duration: 0.5, ease: 'power2.out' }, 0);
  tl.to(capState, {
    o: 1,
    duration: 0.5,
    ease: 'power2.out',
    onUpdate: () => setOpacity(caption, capState.o),
  }, 0);

  // per-word kinetic rise, staggered left to right
  wordWraps.forEach((wrap, i) => {
    const t0 = 0.1 + i * 0.06;
    tl.to(wrap.position, { y: 0, duration: 0.7, ease: 'power3.out' }, t0);
    const st = { o: 0 };
    const target = wordMeta[i].obj;
    tl.to(st, {
      o: 1,
      duration: 0.7,
      ease: 'power3.out',
      onUpdate: () => setOpacity(target, st.o),
    }, t0);
  });

  // weighted settle: group scale 1.04 -> 1.0 as the final glyph lands
  heroGroup.scale.setScalar(1.04);
  tl.to(heroGroup.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, lastGlyphLand);

  // underline reveal, left-anchored, 120ms after the last glyph
  tl.to(rule.scale, { x: 1, duration: 0.5, ease: 'power2.out' }, lastGlyphLand + 0.12);

  // subhead fade-up to y = -0.65
  const subState = { o: 0 };
  tl.to(subheadWrap.position, { y: -0.65, duration: 0.5, ease: 'power2.out' }, lastGlyphLand + 0.35);
  tl.to(subState, {
    o: 1,
    duration: 0.5,
    ease: 'power2.out',
    onUpdate: () => setOpacity(subhead, subState.o),
  }, lastGlyphLand + 0.35);

  // idle: single slow breathing on hero group (<= 2%)
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true, delay: lastGlyphLand + 1.4 });
  idleTl.to(heroGroup.scale, { x: 1.015, y: 1.015, z: 1.015, duration: 3.4, ease: 'sine.inOut' });
  timelines.push(idleTl);

  // ---------------------------------------------------------------
  // handlers + cleanup
  // ---------------------------------------------------------------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    primHandles.forEach((h) => { if (h && h.cleanup) h.cleanup(); });
    disposables.forEach((d) => { if (d && d.dispose) d.dispose(); });
    root.traverse((child) => {
      if (child.geometry && child.geometry.dispose) child.geometry.dispose();
      if (child.material && child.material.dispose) child.material.dispose();
    });
  };

  return root;
}
